export function getCandidateExam(id: string) {
  return CANDIDATE_EXAMS.find((exam) => exam.id === id) ?? null;
}

export type CandidateExamSummary = {
  id: string;
  title: string;
  category: string;
  blurb: string;
  questionCount: number;
};

export function listCandidateExamSummaries(): CandidateExamSummary[] {
  return CANDIDATE_EXAMS.map((exam) => ({
    id: exam.id,
    title: exam.title,
    category: exam.category,
    blurb: exam.blurb,
    questionCount: exam.questions.length,
  }));
}

export function isCandidateExamId(id: string): boolean {
  return CANDIDATE_EXAMS.some((exam) => exam.id === id);
}